#include "ann.h"
#include "ann_console.h"
#include "ann_log.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static ann_node nodes[5];
static ann_console consoles[5];
static int links[5][5],drop_ack,ack_dropped,assertions,failed;
static uint64_t now;
static uint32_t tx_attempt[5];
#define CHECK(x) do{assertions++;if(!(x)){fprintf(stderr,"assertion failed: %s line %d\n",#x,__LINE__);failed++;}}while(0)
static void init(const char*name){unsigned i;memset(links,0,sizeof(links));now=0;memset(tx_attempt,0,sizeof(tx_attempt));drop_ack=ack_dropped=0;for(i=0;i<5;i++){ann_init(&nodes[i],i+1,100+i);ann_console_init(&consoles[i],&nodes[i],"host-synthetic","host-v1");strcpy(consoles[i].run_id,name);if(i<4)links[i][i+1]=links[i+1][i]=1;ann_start(&nodes[i],0);}}
static void drain(void){unsigned i;char line[1024];ann_event e;for(i=0;i<5;i++)while(ann_next_event(&nodes[i],&e)){ann_log_event(&consoles[i],&e,line,sizeof(line));puts(line);}}
static void pump(void){unsigned rounds,i,j;ann_out out;uint8_t bytes[250];char line[1024];int work;for(rounds=0;rounds<100;rounds++){work=0;for(i=0;i<5;i++)while(ann_next_tx(&nodes[i],&out,now)){int z=ann_encode(&out.packet,bytes,sizeof(bytes));CHECK(z>=112&&z<=250);if(z<0)continue;work=1;tx_attempt[i]++;ann_log_tx(&consoles[i],&out,"tx_submit",0,now,tx_attempt[i],line,sizeof(line));puts(line);for(j=0;j<5;j++)if(links[i][j]&&(!out.next||out.next==j+1)){if(drop_ack&&!ack_dropped&&out.packet.type==ANN_ACK){ack_dropped=1;continue;}{uint32_t delivered_before=nodes[j].delivered;ann_receive(&nodes[j],i+1,bytes,(size_t)z,now);if(nodes[j].delivered>delivered_before&&out.packet.kind==ANN_ECHO&&out.packet.dst==nodes[j].id){ann_log_echo(&consoles[j],&out.packet,now,line,sizeof(line));puts(line);}}}ann_tx_result(&nodes[i],&out,!out.next||(out.next<=5&&links[i][out.next-1]),now);ann_log_tx(&consoles[i],&out,"tx_result",!out.next||(out.next<=5&&links[i][out.next-1]),now,tx_attempt[i],line,sizeof(line));puts(line);}drain();if(!work)return;}CHECK(0);}
static void advance(unsigned ms){uint64_t end=now+ms;for(;now<=end;now+=10){unsigned i;for(i=0;i<5;i++)ann_tick(&nodes[i],now);pump();}}
static uint32_t send(unsigned kind,unsigned key,const char*payload,unsigned life){uint32_t seq=0;CHECK(ann_submit(&nodes[0],5,(uint8_t)kind,key,payload,strlen(payload),life,0,now,&seq)==0);return seq;}
static void direct(ann_packet*p){uint8_t b[250];int z=ann_encode(p,b,sizeof(b));CHECK(z>0);CHECK(ann_receive(&nodes[4],1,b,(size_t)z,now)==0);}
static ann_packet packet(unsigned seq,unsigned type){ann_packet p;memset(&p,0,sizeof(p));p.type=(uint8_t)type;p.ttl=8;p.path_len=2;p.index=1;p.path[0]=1;p.path[1]=5;p.origin=1;p.dst=5;p.boot=100;p.seq=seq;p.remaining_ms=2000;p.kind=ANN_TRANSACTION;p.payload_len=1;p.payload[0]='x';return p;}
static void scenario(const char*name){int before=failed;unsigned i;if(!strcmp(name,"chain")){init(name);send(ANN_TRANSACTION,0,"transaction",4000);advance(100);CHECK(nodes[4].delivered==1);CHECK(nodes[0].confirmed==1);CHECK(nodes[0].routes[0].len==5);CHECK(nodes[0].peers[0].id==2);}
 else if(!strcmp(name,"ack_loss")){init(name);drop_ack=1;send(ANN_TRANSACTION,0,"retry",4000);advance(1200);CHECK(ack_dropped);CHECK(nodes[4].delivered==1);CHECK(nodes[4].duplicates>=1);CHECK(nodes[0].confirmed==1);CHECK(nodes[0].pending[0].attempts==2);}
 else if(!strcmp(name,"echo")){uint8_t payload[16]={0};uint32_t seq;init(name);CHECK(!ann_submit(&nodes[0],5,ANN_TRANSACTION,0,payload,sizeof(payload),4000,1,now,&seq));advance(100);CHECK(nodes[0].delivered==1);CHECK(nodes[4].delivered==1);CHECK(nodes[0].confirmed==1);CHECK(nodes[4].confirmed==1);}
 else if(!strcmp(name,"state")){ann_packet p;init(name);p=packet(2,ANN_DATA);p.kind=ANN_STATE;p.key=7;p.payload[0]='b';direct(&p);p.seq=1;p.payload[0]='a';direct(&p);CHECK(nodes[4].states[0].data[0]=='b');CHECK(nodes[4].delivered==1);ann_tick(&nodes[4],2001);CHECK(!nodes[4].states[0].used);drain();}
 else if(!strcmp(name,"expiry")){init(name);links[1][2]=links[2][1]=0;send(ANN_TRANSACTION,0,"expire",100);advance(200);CHECK(!nodes[0].pending[0].used);CHECK(!nodes[4].delivered);}
 else if(!strcmp(name,"cancel")){ann_packet p;uint32_t seq;init(name);seq=send(ANN_TRANSACTION,0,"cancel",4000);CHECK(ann_cancel(&nodes[0],seq,now)==0);advance(100);CHECK(!nodes[4].delivered);p=packet(42,ANN_CANCEL);p.payload_len=0;direct(&p);p=packet(42,ANN_DATA);direct(&p);CHECK(!nodes[4].delivered);CHECK(nodes[4].duplicates==1);}
 else if(!strcmp(name,"error")){init(name);send(ANN_TRANSACTION,0,"first",4000);advance(100);CHECK(nodes[0].confirmed==1);links[1][2]=links[2][1]=0;send(ANN_TRANSACTION,0,"broken",4000);advance(2500);CHECK(nodes[0].confirmed==1);CHECK(!nodes[0].routes[0].used);CHECK(!nodes[0].pending[0].used);}
 else if(!strcmp(name,"reboot")){init(name);send(ANN_TRANSACTION,0,"one",4000);advance(100);CHECK(nodes[4].delivered==1);ann_init(&nodes[0],1,999);ann_start(&nodes[0],now);send(ANN_TRANSACTION,0,"two",4000);advance(100);CHECK(nodes[4].delivered==2);CHECK(nodes[0].confirmed==1);ann_init(&nodes[4],5,888);ann_start(&nodes[4],now);send(ANN_TRANSACTION,0,"receiver-reboot",4000);advance(100);CHECK(nodes[4].delivered==1);CHECK(nodes[0].confirmed==2);}
 else if(!strcmp(name,"bounds")){uint32_t seq;ann_packet p;init(name);for(i=0;i<8;i++)CHECK(ann_submit(&nodes[0],5,ANN_TRANSACTION,0,"x",1,4000,0,0,&seq)==0);CHECK(ann_submit(&nodes[0],5,ANN_TRANSACTION,0,"x",1,4000,0,0,&seq)<0);CHECK(ann_submit(&nodes[0],5,ANN_TRANSACTION,0,"x",139,4000,0,0,&seq)<0);for(i=1;i<=16;i++){p=packet(100+i,ANN_DATA);p.origin=10+i;p.path[0]=p.origin;{uint8_t b[250];int z=ann_encode(&p,b,sizeof(b));CHECK(ann_receive(&nodes[4],p.origin,b,z,0)==0);}}p=packet(200,ANN_DATA);{uint8_t b[250];int z=ann_encode(&p,b,sizeof(b));CHECK(ann_receive(&nodes[4],1,b,z,0)<0);}CHECK(nodes[4].delivered==16);CHECK(nodes[4].rejected==1);ann_stop(&nodes[0],0);CHECK(!nodes[0].out_count);CHECK(ann_submit(&nodes[0],5,ANN_TRANSACTION,0,"x",1,1,0,0,&seq)<0);drain();}
 else if(!strcmp(name,"continuous")){ann_packet old;init(name);for(i=0;i<100;i++){send(ANN_TRANSACTION,0,"series",4000);advance(10);}CHECK(nodes[4].delivered==100);CHECK(nodes[0].confirmed==100);old=packet(1,ANN_DATA);direct(&old);CHECK(nodes[4].delivered==100);CHECK(nodes[4].duplicates>=1);}
 else if(!strcmp(name,"wire")){ann_packet p,q;uint8_t b[250];unsigned seed=7;int z;init(name);p=packet(1,ANN_DATA);p.payload_len=138;memset(p.payload,0xa5,138);z=ann_encode(&p,b,250);CHECK(z==250);CHECK(!ann_decode(&q,b,250));CHECK(q.payload_len==138&&q.payload[137]==0xa5);b[200]^=1;CHECK(ann_decode(&q,b,250)<0);CHECK(ann_decode(&q,b,111)<0);p.index=8;z=ann_encode(&p,b,250);CHECK(z>0&&ann_decode(&q,b,z)<0);for(i=0;i<5000;i++){size_t j,len=i%251;for(j=0;j<len;j++){seed=1664525*seed+1013904223;b[j]=(uint8_t)(seed>>24);}CHECK(ann_decode(&q,b,len)<0);}drain();}
 else if(!strcmp(name,"serial")){ann_node n;ann_console c;char out[1024];const char*cmd;ann_init(&n,1,11);ann_console_init(&c,&n,"host-synthetic","host-v1");
#define CMD(s,expect) do{cmd=s;CHECK((ann_command(&c,cmd,strlen(cmd),out,sizeof(out),n.now)==0)==expect);puts(out);}while(0)
 CMD("{\"cmd\":\"info\",\"nonce\":\"probe123\"}",1);CHECK(!n.active&&!n.out_count);CHECK(strstr(out,"host-synthetic")&&strstr(out,"probe123"));
 CMD("{\"cmd\":\"bench\",\"nonce\":\"b\",\"run_id\":\"r1\"}",0);CHECK(!n.active);
 CMD("{\"cmd\":\"info\",\"cmd\":\"stop\",\"nonce\":\"n\"}",0);
 CMD("{\"cmd\":\"info\",\"nonce\":\"n\"}garbage",0);
 CMD("{\"cmd\":\"erase\",\"nonce\":\"n\"}",0);
 CMD("{\"cmd\":\"arm\",\"nonce\":\"a\",\"node_id\":\"00:00:00:00:00:02\",\"run_id\":\"r1\",\"duration_ms\":60000}",0);
 CMD("{\"cmd\":\"arm\",\"nonce\":\"a\",\"node_id\":\"00:00:00:00:00:01\",\"run_id\":\"r1\",\"duration_ms\":60000}",1);CHECK(!n.active&&!n.out_count);
 CMD("{\"cmd\":\"bench\",\"nonce\":\"b\",\"run_id\":\"r1\",\"dst\":\"00:00:00:00:00:05\",\"count\":1001,\"interval_ms\":100,\"frame_bytes\":128,\"echo\":true}",0);CHECK(!n.active);
 CMD("{\"cmd\":\"bench\",\"nonce\":\"b\",\"run_id\":\"r1\",\"dst\":\"00:00:00:00:00:05\",\"count\":2,\"interval_ms\":100,\"frame_bytes\":128,\"echo\":true}",1);CHECK(n.active);ann_console_tick(&c,0);CHECK(c.sent==1);ann_console_tick(&c,100);CHECK(c.sent==2);
 CMD("{\"cmd\":\"stop\",\"nonce\":\"s\"}",1);CHECK(!n.active&&!c.armed&&!n.out_count);
 CMD("{\"cmd\":\"stats\",\"nonce\":\"s\"}",1);CHECK(strstr(out,"\"airtime_us\":null")!=NULL);
 {char too_long[513];memset(too_long,'x',sizeof(too_long));CHECK(ann_command(&c,too_long,513,out,sizeof(out),0)<0);}
#undef CMD
 }else{fprintf(stderr,"unknown scenario %s\n",name);failed++;}
 printf("{\"schema\":\"ann.test.v1\",\"scenario\":\"%s\",\"passed\":%s,\"evidence_kind\":\"synthetic\"}\n",name,failed==before?"true":"false");}
int main(int argc,char**argv){if(argc==2&&!strcmp(argv[1],"--console")){ann_node n;ann_console c;char line[1024],out[1024];ann_event e;ann_out tx;uint64_t t=0;uint32_t attempt=0;ann_init(&n,1,1);ann_console_init(&c,&n,"host-synthetic","host-v1");while(fgets(line,sizeof(line),stdin)){size_t z=strlen(line);if(z&&line[z-1]=='\n')z--;if(z&&line[z-1]=='\r')z--;ann_command(&c,line,z,out,sizeof(out),t);puts(out);ann_console_tick(&c,t);while(ann_next_event(&n,&e)){ann_log_event(&c,&e,out,sizeof(out));puts(out);}while(ann_next_tx(&n,&tx,t)){ann_log_tx(&c,&tx,"tx_submit",-1,t,++attempt,out,sizeof(out));puts(out);ann_tx_result(&n,&tx,0,t);ann_log_tx(&c,&tx,"tx_result",0,t,attempt,out,sizeof(out));puts(out);}t+=10;}ann_stop(&n,t);return 0;}if(argc!=3||strcmp(argv[1],"--scenario")){fprintf(stderr,"usage: ann_host --scenario NAME | --console\n");return 2;}if(!strcmp(argv[2],"all")){const char*cases[]={"chain","ack_loss","echo","state","expiry","cancel","error","reboot","bounds","continuous","wire","serial"};unsigned i;for(i=0;i<sizeof(cases)/sizeof(*cases);i++)scenario(cases[i]);}else scenario(argv[2]);printf("{\"schema\":\"ann.test.v1\",\"assertions\":%d,\"failures\":%d,\"evidence_kind\":\"synthetic\"}\n",assertions,failed);return failed?1:0;}
